import React from 'react'
import { connect } from 'react-redux'
import {
  Card,
  Row,
  Col,
  Button,
  Radio,
  notification,
  Divider,
  Icon
} from 'antd'
import HomeStyle from './home.style'
import claimActions from '../../../redux/claim/actions'
import IntlMessages from '../../../components/utility/intlMessages'
import { injectIntl } from 'react-intl'

const RadioGroup = Radio.Group
const { getBenefits, postClaim, resetReduxState } = claimActions

class Home extends React.Component {
  constructor (props) {
    super(props)
    this.state = {
      claimType:
        window.sessionStorage.getItem('claimType') !== undefined ? window.sessionStorage.getItem('claimType') : '',
      failedGetBenefitLists: '',
      data: [],
      loading: true,
      createClaimStatus: '',
      claimId: '',
      loadingClaim: false,
      activeClaim: true,
      canNotFetchBenefitsMessage: '',
      index: null,
      notifications: {},
      dottedCard: false,
      dottedCardShow: false,
      dottedIndex: null,
      simpleCard: false
    }
  }
  intlText = (messageObj = { id: ' ' }) => {
    return this.props.intl.formatMessage(messageObj)
  }
  componentWillMount () {
    const { location, match, history } = this.props
    const payloadFromPolicyDetail = window.sessionStorage.getItem('toPolicyDetail')
    if (location.state === undefined && payloadFromPolicyDetail === undefined) {
      history.push(`/policydetail/${match.params.id}`)
    }
  }
  componentWillReceiveProps (nextProps) {
    const { data, failedGetBenefitLists, createClaimStatus, claimId } = nextProps.benefits
    if (createClaimStatus !== '' && createClaimStatus !== 'success') {
      if (this.state.notifications.createClaimStatus === undefined || this.state.notifications.createClaimStatus !== true) {
        notification['error']({
          message: this.intlText({ id: createClaimStatus }),
          description: '',
          onClose: () => {
            this.setState({
              notifications: {
                ...this.state.notifications,
                createClaimStatus: false
              }
            })
          }
        })
      }
      this.setState({
        notifications: {
          ...this.state.notifications,
          createClaimStatus: true
        }
      })
      this.props.resetReduxState()
    }
    if (createClaimStatus !== '' && createClaimStatus === 'success') {
      window.sessionStorage.setItem('claim', claimId)
      this.setState({
        notifications: {
          ...this.state.notifications,
          createClaimStatus: false
        }
      })
      this.props.resetReduxState()
    }
    if (createClaimStatus !== '') {
      window.sessionStorage.setItem('claim',claimId)
      this.setState({
        createClaimStatus,
        claimId,
        loadingClaim: false
      })
    }
    if (failedGetBenefitLists !== '') {
      this.setState({
        failedGetBenefitLists,
        loading: false
      })
    } else {
      this.setState({
        data,
        loading: false
      })
    }
  }
  radioButtonClick = i => {
    if (this.state.index === i) {
      this.setState({
        index: -1
      })
    } else {
      this.setState({
        index: i
      })
    }
  }
  onCardClick = (i, cardType) => {
    if (cardType === 'simple') {
      this.setState(
        {
          dottedCard: false,
          simpleCard: true,
          dottedCardShow: false
        },
        () => {
          this.radioButtonClick(i)
        }
      )
    } else if (cardType === 'dotted') {
      this.setState(
        {
          simpleCard: false,
          dottedCard: true
        },
        () => {
          this.setState({
            dottedCardShow: false
          })
          this.radioButtonClick(i)
        }
      )
    } else {
      this.radioButtonClick(i)
    }
  }

  onShowContent = i => {
    if (this.state.dottedIndex !== i) {
      this.setState(
        {
          dottedCard: false
        },
        () => {
          this.setState({
            dottedIndex: i,
            dottedCardShow: !this.state.dottedCardShow
          })
        })
    }
  }

  renderBenefitCard = (val, index) => {
    if (val.benefits.length < 2) {
      return val.benefits.map((d, Index) => {
        return (
          <RadioGroup onChange={(e) => {
            this.setState({
              claimType: e.target.value
            }, () => {
            })
          }} value={this.state.claimType}>

            <Radio.Button value={d} onClick={() => { this.onCardClick(index, 'simple') }} className={(this.state.index === index && this.state.simpleCard) ? 'active-card claims-card' : 'claims-card'} style={{ width: '90%', height: 60, borderStyle: 'none' }}>
              <Row className='benefit-list-row' key={index}>
                {/* <Col xs={2} xl={1} lg={1} md={1} >
                                        <Radio  style={{display:'none'}} value={d} />
                                    </Col> */}
                <Col xs={22} xl={23} lg={23} md={23}>
                  <strong>
                    <IntlMessages id={d.benefit_name} />
                  </strong>
                </Col>
              </Row>
            </Radio.Button>

          </RadioGroup>
        )
      })
    } else {
      return (
        <RadioGroup onChange={(e) => {
          this.setState({
            claimType: e.target.value
          }, () => {
          })
        }} value={this.state.claimType} >
          <div onClick={() => this.onShowContent(index)} className={(this.state.dottedIndex === index && this.state.dottedCard) ? 'active-card claims-card ' : 'claims-card'} style={{ width: '90%' }}>

            <Row style={{ cursor: 'pointer' }} >
              <Col xs={20}>
                <p className='b-card-heading'><IntlMessages id={val.benefit_group_name} /></p>
                <p className='b-card-subheading'><IntlMessages id={val.benefit_group_description} /></p>
              </Col>
              <Col xs={4}>
                <p className='icon-caret' onClick={() => this.onShowContent(index)} >
                  <span className='dots' style={{ background: this.state.dottedCard ? 'white' : '#fcd300' }} />
                  <span className='dots' style={{ background: this.state.dottedCard ? 'white' : '#fcd300', marginTop: 2 }} />
                  <span className='dots' style={{ background: this.state.dottedCard ? 'white' : '#fcd300', marginTop: 2 }} />
                </p>
              </Col>
            </Row>
            {

              this.state.dottedIndex === index &&
              this.state.dottedCardShow &&
              <div>
                <Divider />
                <p className='heading-benefit'><IntlMessages id='Pilih Manfaat' /></p>
                {
                  val.benefits.map((d, index) => {
                    return (
                      <Row className='benefit-list-row' key={index} style={{ marginBottom: '20px' }}>
                        <Col xs={2} xl={1} lg={1} md={1}>
                          <Radio value={d} onClick={() => { this.onCardClick(index, 'dotted') }} />

                        </Col>
                        <Col xs={22} xl={23} lg={23} md={23} style={{ paddingLeft: 20 }}>
                          <IntlMessages id={d.benefit_name} />
                        </Col>
                      </Row>
                    )
                  })
                }
              </div>
            }
          </div>
        </RadioGroup>
      )
    }
  }
  noBenefitInfo = () => {
    return (
      <Card>
        <h3>
          <IntlMessages id='Anda dalam perlindungan yang tepat' />
        </h3>
        <p>
          <IntlMessages id='Untuk info lebih lengkap hubungi customer service kami pada nomor di bawah ini' />{' '}
          &amp; <IntlMessages id='daftarkan klaim anda' />
        </p>
        {/* <span style={{ fontSize: '24px' }}>
          <i className='fas fa-phone-volume' />
          &nbsp;&nbsp;021 5089 0580
        </span>
        <br />
        <br />
        - <IntlMessages id='ATAU' /> -
        <br />
        <br /> */}
        <p>
          <IntlMessages id='Chat dengan customer service kami melalu nomor whatsapp dibawah ini' />{' '}
          &amp; <IntlMessages id='daftarkan klaim anda' />
        </p>
        <span style={{ fontSize: '24px' }}>
          <i className='fab fa-whatsapp' /> &nbsp;&nbsp;(+62) 818 343 494
        </span>
      </Card>
    )
  }
  componentDidMount () {
    const { state } = this.props.location
    const payloadFromPolicyDetail = window.sessionStorage.getItem('toPolicyDetail')
    if (
      Object.values(payloadFromPolicyDetail).length > 1 ||
      state !== undefined
    ) {
      const strToLower = payloadFromPolicyDetail.packageName.toLowerCase()
      const pkg = strToLower.replace(new RegExp(' ', 'g'), '-')
      this.props.getBenefits({
        package: pkg,
        product: payloadFromPolicyDetail.product
      })
    }
  }
  next = () => {
    const { claimType } = this.state
    this.setState({ loadingClaim: true })
    const payloadFromPolicyDetail = window.sessionStorage.getItem('toPolicyDetail')
    if (claimType.is_claim_active) {
      this.props.postClaim(
        {
          benefitId: claimType.benefit_id,
          applicationNo: payloadFromPolicyDetail.applicationNo
        }
      )
    } else {
      this.setState({ loadingClaim: false, activeClaim: false })
    }
  }
  goToDetailPolicyList = () => {
    const { history, match } = this.props
    window.sessionStorage.removeItem('toPolicyDetail')
    history.push(`/policydetail/${match.params.id}`)
  }
  render () {
    const {
      claimType,
      data,
      failedGetBenefitLists,
      loading,
      createClaimStatus,
      claimId
    } = this.state
    const { history } = this.props
    if (createClaimStatus !== '' && createClaimStatus === 'success') {
      const payloadFromPolicyDetail = window.sessionStorage.getItem('toPolicyDetail')
      history.push({
        pathname: `/claimdetail/${claimId === '' ? window.sessionStorage.getItem('claim') : claimId}`,
        state: {
          benefitId: claimType,
          applicationNo: payloadFromPolicyDetail.applicationNo,
          packageName: payloadFromPolicyDetail.packageName,
          claimId: claimId === '' ? window.sessionStorage.getItem('claim') : claimId
        }
      })
    }
    return (
      <HomeStyle>
        <Row style={{ display: 'flex', justifyContent: 'center' }}>
          <Col xs={24} sm={24} md={12} lg={12} xl={12}>
            {failedGetBenefitLists !== '' && (
              <Row style={{ display: 'flex', justifyContent: 'center' }}>
                <Col span={24}>
                  <Card>
                    {this.noBenefitInfo()}
                    <Button
                      className='btn-cancel'
                      style={{
                        float: 'right',
                        marginTop: '15px',
                        marginLeft: '15px'
                      }}
                      onClick={this.goToDetailPolicyList}
                    >
                      <IntlMessages id='Kembali' />
                    </Button>
                  </Card>
                </Col>
              </Row>
            )}
            {loading ? (
              <center>
                <Icon
                  type='loading'
                  className='loader'
                  style={{ marginTop: '100px' }}
                />
              </center>
            ) : (
              failedGetBenefitLists === '' && (
                <div>
                  {this.state.activeClaim && (
                    <span>
                      <h2 className='form-title'>
                        <IntlMessages id='Pilih benefit untuk klaim' />.
                      </h2>
                      {data.length > 0
                        ? data.map((val, index) =>
                          this.renderBenefitCard(val, index)
                        )
                        : this.noBenefitInfo() // change this to benefit info
                      }
                      <Row>
                        <Col
                          className='btn-container'
                          span={24}
                          style={{
                            display: 'flex',
                            justifyContent: 'center',
                            alignItems: 'center',
                            flexDirection: 'row'
                          }}
                        >
                          <Button
                            className='button-cancel'
                            style={{ marginTop: '15px', marginRight: '15px' }}
                            onClick={this.goToDetailPolicyList}
                          >
                            <IntlMessages id='Kembali' />
                          </Button>
                          <Button
                            className='button-claim'
                            htmlType='submit'
                            style={{ marginTop: '15px' }}
                            disabled={claimType.length < 1}
                            onClick={this.next}
                            loading={this.state.loadingClaim}
                          >
                            <IntlMessages id='Klaim' />
                          </Button>
                        </Col>
                      </Row>
                    </span>
                  )}
                  {!this.state.activeClaim && (
                    <Card>
                      <Row>
                        <Row>{this.noBenefitInfo()}</Row>
                      </Row>
                      <Button
                        className='btn-cancel'
                        style={{
                          float: 'right',
                          marginTop: '15px',
                          marginLeft: '15px'
                        }}
                        onClick={this.goToDetailPolicyList}
                      >
                        <IntlMessages id='Kembali' />
                      </Button>
                    </Card>
                  )}
                </div>
              )
            )}
          </Col>
        </Row>
      </HomeStyle>
    )
  }
}

export default connect(
  state => ({
    benefits: state.Claim
  }),
  { getBenefits, postClaim, resetReduxState }
)(injectIntl(Home))
